        assertEquals(Integer.class, result.getContentType().getRawClass());

        // Test TreeMap shortcut
        JavaType resultTree = typeFactory.constructSpecializedType(baseType, TreeMap.class);
        assertEquals(TreeMap.class, resultTree.getRawClass());
    }












}

